    "name": "001_init.sql",
    "sql": "-- Cost Seg Trust: initial schema\n-- Works on any Postgres 14+ (Supabase, Neon, RDS). The app connects with a\n-- server-side connection string only; nothing here is exposed to browsers.\n\ncreate extension if not exists pgcrypto;\ncreate extension if not exists citext;\n\n-- Deal stages mirror the HubSpot pipeline one-to-one.\ndo $$ begin\n  create type deal_stage as enum (\n    'new_request', 'waiting_on_quotes', 'quotes_received', 'comparison_ready',\n    'awaiting_approval', 'sent_to_client', 'closed'\n  );\nexception when duplicate_object then null; end $$;\n\ndo $$ begin\n  create type closed_outcome as enum ('won', 'lost');\nexception when duplicate_object then null; end $$;\n\n-- One row per person who requests quotes. Email is the dedupe key, matching\n-- how HubSpot dedupes contacts.\ncreate table if not exists clients (\n  id                 uuid primary key default gen_random_uuid(),\n  email              citext not null unique,\n  first_name         text not null,\n  last_name          text not null default '',\n  phone              text,\n  hubspot_contact_id text unique,\n  created_at         timestamptz not null default now(),\n  updated_at         timestamptz not null default now()\n);\n\ncreate sequence if not exists deal_number_seq start 1001;\n\ncreate table if not exists deals (\n  id                    uuid primary key default gen_random_uuid(),\n  number                integer not null unique default nextval('deal_number_seq'),\n  -- Generated by the browser for each form load; a double-click or retry\n  -- with the same key never creates a second deal.\n  request_key           uuid not null unique,\n  client_id             uuid not null references clients(id),\n  stage                 deal_stage not null default 'new_request',\n  closed_outcome        closed_outcome,\n  property_address      text not null,\n  property_city_state   text,\n  property_type         text not null,\n  purchase_price        numeric(14,2) not null check (purchase_price > 0),\n  placed_in_service     date not null,\n  land_value            text,\n  renovation_spend      numeric(14,2),\n  has_cpa               boolean,\n  client_notes          text,\n  consent_contact       boolean not null,\n  consent_at            timestamptz not null,\n  utm_source            text,\n  utm_medium            text,\n  utm_campaign          text,\n  admin_notes           text,\n  hubspot_deal_id       text unique,\n  hubspot_sync_status   text not null default 'pending' check (hubspot_sync_status in ('pending','synced','failed','skipped')),\n  hubspot_synced_at     timestamptz,\n  hubspot_error         text,\n  created_at            timestamptz not null default now(),\n  updated_at            timestamptz not null default now()\n);\ncreate index if not exists deals_stage_idx on deals(stage);\ncreate index if not exists deals_created_idx on deals(created_at desc);\n\n-- Audit trail shown on the deal page.\ncreate table if not exists deal_events (\n  id          bigserial primary key,\n  deal_id     uuid not null references deals(id) on delete cascade,\n  kind        text not null,\n  detail      jsonb not null default '{}'::jsonb,\n  created_at  timestamptz not null default now()\n);\ncreate index if not exists deal_events_deal_idx on deal_events(deal_id, created_at);\n\n-- Every email/SMS the system tries to send, with its result.\ncreate table if not exists notifications (\n  id           bigserial primary key,\n  deal_id      uuid references deals(id) on delete cascade,\n  channel      text not null check (channel in ('email','sms')),\n  recipient    text not null,\n  purpose      text not null,\n  status       text not null check (status in ('sent','failed','skipped')),\n  provider_id  text,\n  error        text,\n  created_at   timestamptz not null default now()\n);\n\ncreate table if not exists suppliers (\n  id            uuid primary key default gen_random_uuid(),\n  company_name  text not null,\n  contact_name  text,\n  email         citext not null unique,\n  phone         text,\n  description   text,\n  is_test       boolean not null default false,\n  active        boolean not null default true,\n  notes         text,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now()\n);\n\n-- Stage 2 (supplier quoting). Created now so the structure is complete.\n-- Suppliers reach their invite through a personalized link; only a SHA-256\n-- hash of the token is stored.\ncreate table if not exists supplier_invites (\n  id              uuid primary key default gen_random_uuid(),\n  deal_id         uuid not null references deals(id) on delete cascade,\n  supplier_id     uuid not null references suppliers(id),\n  token_hash      text not null unique,\n  status          text not null default 'invited' check (status in ('invited','viewed','submitted','declined','expired')),\n  invited_at      timestamptz not null default now(),\n  due_at          timestamptz not null default now() + interval '40 hours',\n  reminder_sent_at timestamptz,\n  viewed_at       timestamptz,\n  responded_at    timestamptz,\n  unique (deal_id, supplier_id)\n);\n\ncreate table if not exists supplier_quotes (\n  id                         uuid primary key default gen_random_uuid(),\n  invite_id                  uuid not null unique references supplier_invites(id) on delete cascade,\n  fee                        numeric(12,2),\n  study_type                 text,\n  site_visit                 boolean,\n  turnaround_days            integer,\n  reclassified_pct           numeric(5,2),\n  est_first_year_deduction   numeric(14,2),\n  est_first_year_tax_savings numeric(14,2),\n  assumed_tax_rate           numeric(5,2),\n  audit_support              text,\n  includes_lookback          boolean,\n  payment_terms              text,\n  valid_days                 integer,\n  comments                   text,\n  proposal_file_path         text,\n  ai_extracted               jsonb,\n  ai_filled_fields           text[] not null default '{}',\n  submitted_at               timestamptz not null default now()\n);\n\n-- Stage 3 (AI comparison + approval).\ncreate table if not exists comparisons (\n  id             uuid primary key default gen_random_uuid(),\n  deal_id        uuid not null unique references deals(id) on delete cascade,\n  status         text not null default 'draft' check (status in ('draft','approved','sent')),\n  summary        text,\n  hidden_rows    text[] not null default '{}',\n  hidden_invites uuid[] not null default '{}',\n  overrides      jsonb not null default '{}'::jsonb,\n  anonymize      boolean not null default false,\n  approved_at    timestamptz,\n  sent_at        timestamptz,\n  created_at     timestamptz not null default now(),\n  updated_at     timestamptz not null default now()\n);\n\n-- Small key/value store (e.g. cached HubSpot pipeline and stage ids).\ncreate table if not exists app_settings (\n  key        text primary key,\n  value      jsonb not null,\n  updated_at timestamptz not null default now()\n);\n\ncreate or replace function touch_updated_at() returns trigger language plpgsql as $$\nbegin new.updated_at = now(); return new; end $$;\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['clients','deals','suppliers','comparisons'] loop\n    execute format('drop trigger if exists %I_touch on %I', t, t);\n    execute format('create trigger %I_touch before update on %I for each row execute function touch_updated_at()', t, t);\n  end loop;\nend $$;\n\n-- Supabase exposes the public schema through its REST API to the \"anon\" and\n-- \"authenticated\" roles. This app never uses that API, so lock every table\n-- with row level security and no policies: only the server connection\n-- (table owner) can read or write.\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['clients','deals','deal_events','notifications','suppliers','supplier_invites','supplier_quotes','comparisons','app_settings'] loop\n    execute format('alter table %I enable row level security', t);\n  end loop;\nend $$;\n"
